SELECT a FROM t WHERE a ISNULL;

SELECT a FROM t WHERE a NOTNULL;

SELECT a FROM t WHERE a NOT NULL;

SELECT a NOT NULL AS is_set, b ISNULL AS is_missing FROM t;

SELECT a FROM t WHERE a == 1 AND b==c;

SELECT a FROM t WHERE a + 1 NOTNULL OR b ISNULL;

CREATE TABLE t2 (
    a INTEGER DEFAULT 0 NOT NULL,
    b TEXT DEFAULT 'x' NOT NULL COLLATE NOCASE,
    c TEXT DEFAULT ('x') NOT NULL,
    d INTEGER DEFAULT -1 NOT NULL,
    e INTEGER CHECK (e NOTNULL)
);

ALTER TABLE t ADD COLUMN f INTEGER DEFAULT 0 NOT NULL;
